// Count ONLY real Salesforce Account rows.
// With onError: continueRegularOutput, a failed fetch emits a single error
// item (e.g. { error: ... }) instead of zero items. Counting raw items would
// make _sfAccountCount = 1 and bypass the empty-Salesforce guard downstream,
// so we count only items that have a truthy Id and no error key.
const valid = $input.all().filter((i) => {
  const j = (i && i.json) || {};
  return !j.error && Boolean(j.Id || j.id);
});
return [{ json: { _sfReady: true, _sfAccountCount: valid.length } }];

// ── Prepare Funding Discovery ─────────────────────────────────────────────
// Builds the Anthropic web-search request for software/tech companies that
// received funding in the last 7 days. Code node mode: "Run Once for All Items".

const MODEL = "claude-haiku-4-5-20251001";

const end = new Date();
const start = new Date();
start.setDate(end.getDate() - 7);

const fmt = (d) => d.toISOString().slice(0, 10);
const startDate = fmt(start);
const endDate = fmt(end);

const prompt = `You are a B2B research assistant for AssureSoft, a nearshore software engineering company.

Find software / technology companies that announced or closed a funding round between ${startDate} and ${endDate} (inclusive).

Search Crunchbase, TechCrunch, LinkedIn, and the web for recent funding news.

Filters (ALL required):
1. Funding announced or closed in the last 7 days (${startDate} to ${endDate})
2. Industry is software / tech (SaaS, software products, developer tools, AI/ML platforms, fintech software, cybersecurity, cloud/infra software, data platforms, etc.). Exclude pure biotech hardware, restaurants, retail stores, real estate agencies, and non-software industrials.

Return ONLY a valid JSON array — no markdown, no explanation. Each element:
{
  "company_name": "<legal or common company name>",
  "website": "<https://... or empty string>",
  "company_description": "<one sentence what the company does>",
  "industry": "<e.g. Software | SaaS | Artificial Intelligence | Cybersecurity | FinTech | Developer Tools>",
  "employee_count": "<integer string or empty, e.g. 45>",
  "billing_city": "<city or empty>",
  "billing_state": "<state/province or empty>",
  "billing_country": "<country or empty>",
  "funding_stage": "<Pre-Seed | Seed | Series A | Series B | Series C | Series D+ | Growth Equity | PE Buyout | Debt | Other | Unknown>",
  "funding_amount": "<e.g. $12M | Undisclosed | Unknown>",
  "funding_date": "<YYYY-MM-DD or YYYY-MM if day unknown>",
  "investors": "<comma-separated investor names, or empty>",
  "crunchbase_url": "<https://www.crunchbase.com/organization/[slug] or empty>"
}

Rules:
- Only include companies you can corroborate via search — do NOT fabricate
- Prefer 15–40 high-confidence matches over a long speculative list
- If employee_count is a range, use the midpoint as an integer string
- website should be the company homepage when known
- If nothing qualifies, return []`;

const _claudeBody = {
  model: MODEL,
  max_tokens: 8000,
  tools: [{ type: "web_search_20250305", name: "web_search" }],
  messages: [{ role: "user", content: prompt }],
};

return [{
  json: {
    _startDate: startDate,
    _endDate: endDate,
    _claudeBody,
  },
}];

// ── Parse Funding Discovery ───────────────────────────────────────────────
// Parses Claude's JSON array into one n8n item per company, shaped for
// Salesforce Account create + email digest.
// Code node mode: "Run Once for All Items".

function nodeJson(name) {
  try { return $(name).first().json; } catch (e) { return null; }
}

function clean(v, def = "") {
  return String(v != null ? v : def).trim();
}

function parseEmployeeCount(raw) {
  const s = clean(raw);
  if (!s || /^unknown$/i.test(s)) return null;
  const range = s.match(/(\d+)\s*[-–]\s*(\d+)/);
  if (range) return Math.round((Number(range[1]) + Number(range[2])) / 2);
  const n = s.replace(/,/g, "").match(/\d+/);
  return n ? Number(n[0]) : null;
}

function buildDescription(d) {
  const lines = [];
  const desc = clean(d.company_description);
  if (desc) lines.push(desc);
  lines.push("");
  lines.push(`Funding: ${clean(d.funding_stage, "Unknown")} | ${clean(d.funding_amount, "Unknown")} | ${clean(d.funding_date, "Unknown")}`);
  const investors = clean(d.investors);
  if (investors) lines.push(`Investors: ${investors}`);
  const cb = clean(d.crunchbase_url);
  if (cb) lines.push(`Crunchbase: ${cb}`);
  const team = clean(d.employee_count);
  if (team) lines.push(`Team size: ${team}`);
  lines.push("Source: Weekly Crunchbase funding discovery (n8n)");
  return lines.join("\n").trim();
}

const meta = nodeJson("Prepare Funding Discovery") || {};
const startDate = meta._startDate || "";
const endDate = meta._endDate || "";

let companies = [];
let parseError = "";

try {
  const resp = nodeJson("Claude Funding Discovery");
  if (!resp) {
    parseError = "No response from Claude Funding Discovery";
  } else if (resp.error) {
    parseError = String(resp.error.message || resp.error).slice(0, 300);
  } else if (Array.isArray(resp.content)) {
    const text = resp.content
      .filter((b) => b && b.type === "text" && b.text)
      .map((b) => b.text)
      .join(" ");
    const m = text.match(/\[[\s\S]*\]/);
    if (!m) throw new Error("No JSON array in Claude response");
    const parsed = JSON.parse(m[0]);
    if (!Array.isArray(parsed)) throw new Error("Parsed JSON is not an array");
    companies = parsed;
  } else {
    parseError = "Unexpected Claude response shape";
  }
} catch (e) {
  parseError = String(e.message || e).slice(0, 300);
}

if (!companies.length) {
  return [{
    json: {
      _empty: true,
      _parseError: parseError,
      _startDate: startDate,
      _endDate: endDate,
      company_name: "",
      Name: "",
      Website: "",
      Description: "",
      Industry: "",
      NumberOfEmployees: null,
      BillingCity: "",
      BillingState: "",
      BillingCountry: "",
      funding_stage: "",
      funding_amount: "",
      funding_date: "",
      investors: "",
      crunchbase_url: "",
      employee_count: "",
    },
  }];
}

return companies.map((d) => {
  const name = clean(d.company_name);
  const website = clean(d.website);
  const employees = parseEmployeeCount(d.employee_count);
  return {
    json: {
      _empty: false,
      _parseError: "",
      _startDate: startDate,
      _endDate: endDate,
      company_name: name,
      Name: name,
      Website: website,
      Description: buildDescription(d),
      Industry: clean(d.industry, "Software"),
      NumberOfEmployees: employees,
      BillingCity: clean(d.billing_city),
      BillingState: clean(d.billing_state),
      BillingCountry: clean(d.billing_country),
      funding_stage: clean(d.funding_stage),
      funding_amount: clean(d.funding_amount),
      funding_date: clean(d.funding_date),
      investors: clean(d.investors),
      crunchbase_url: clean(d.crunchbase_url),
      employee_count: clean(d.employee_count),
      company_description: clean(d.company_description),
    },
  };
});

// ── Dedupe vs Salesforce ──────────────────────────────────────────────────
// Marks each discovered company as new or existing using Account Name OR
// Website domain (normalized). Code node mode: "Run Once for All Items".

function normalizeName(n) {
  return String(n || "")
    .toLowerCase()
    .replace(/&/g, "and")
    .replace(/[^a-z0-9]/g, "");
}

function normalizeDomain(url) {
  let s = String(url || "").trim().toLowerCase();
  if (!s) return "";
  s = s.replace(/^https?:\/\//, "").replace(/^www\./, "");
  return s.split("/")[0].split("?")[0];
}

function sfAccounts() {
  try {
    // Only real Account rows. onError: continueRegularOutput can emit a single
    // error item on a failed fetch; counting/matching it would let the empty-SF
    // guard pass and mark every company new. Require truthy Id and no error key.
    return $("Get Salesforce Accounts")
      .all()
      .map((i) => i.json)
      .filter((j) => j && !j.error && Boolean(j.Id || j.id));
  } catch (e) {
    return [];
  }
}

const accounts = sfAccounts();
const items = $input.all();

return items.map((item) => {
  const c = item.json;
  if (c._empty || !c.Name) {
    return {
      json: {
        ...c,
        _isNew: false,
        _skipCreate: true,
        _matchReason: "empty",
        _sfAccountCount: accounts.length,
      },
    };
  }

  const name = normalizeName(c.Name);
  const domain = normalizeDomain(c.Website);

  let matchReason = "";
  let matchedId = "";

  for (const sf of accounts) {
    const sfName = normalizeName(sf.Name);
    const sfDomain = normalizeDomain(sf.Website);
    const nameMatch = Boolean(name && sfName && name === sfName);
    const domainMatch = Boolean(domain && sfDomain && domain === sfDomain);
    if (nameMatch || domainMatch) {
      matchReason = nameMatch && domainMatch
        ? "name+website"
        : nameMatch
          ? "name"
          : "website";
      matchedId = sf.Id || sf.id || "";
      break;
    }
  }

  const isNew = !matchReason;
  return {
    json: {
      ...c,
      _isNew: isNew,
      _skipCreate: !isNew,
      _matchReason: matchReason || "none",
      _matchedAccountId: matchedId,
      _sfAccountCount: accounts.length,
    },
  };
});

// ── Build Funding Digest (CSV rows) ───────────────────────────────────────
// Emits one clean row per discovered company for Convert to File.
// Email subject/body are assembled later in Finalize Email (keeps CSV clean).
// Code node mode: "Run Once for All Items".

const all = $input.all().map((i) => i.json);
const companies = all.filter((c) => !c._empty && c.Name);

if (!companies.length) {
  return [{
    json: {
      company_name: "",
      website: "",
      industry: "",
      employee_count: "",
      billing_city: "",
      billing_state: "",
      billing_country: "",
      funding_stage: "",
      funding_amount: "",
      funding_date: "",
      investors: "",
      crunchbase_url: "",
      company_description: "",
      salesforce_status: "none",
      match_reason: "",
    },
  }];
}

const guardTripped = (companies[0] && companies[0]._sfAccountCount === 0);

return companies.map((c) => ({
  json: {
    company_name: c.Name,
    website: c.Website,
    industry: c.Industry,
    employee_count: c.employee_count || c.NumberOfEmployees || "",
    billing_city: c.BillingCity,
    billing_state: c.BillingState,
    billing_country: c.BillingCountry,
    funding_stage: c.funding_stage,
    funding_amount: c.funding_amount,
    funding_date: c.funding_date,
    investors: c.investors,
    crunchbase_url: c.crunchbase_url,
    company_description: c.company_description || "",
    salesforce_status: guardTripped ? "skipped (SF fetch empty)" : (c._isNew ? "new" : "existing"),
    match_reason: c._matchReason || "",
  },
}));

// ── Finalize Email ────────────────────────────────────────────────────────
// Runs after Convert to File. Keeps the CSV binary and sets the email
// subject/body based on the run outcome:
//   - soft failure (Claude/parse errored but flow continued) -> ⚠️ notice
//   - SF guard tripped (0 accounts fetched) -> ⚠️ digest, creation SKIPPED
//   - companies found -> ✅ digest (CSV attached)
//   - no companies    -> ✅ "no matches"
// Code node mode: "Run Once for All Items".

let deduped = [];
try {
  deduped = $("Dedupe vs Salesforce").all().map((i) => i.json);
} catch (e) {
  deduped = [];
}

const companies = deduped.filter((c) => !c._empty && c.Name);
const startDate = (companies[0] && companies[0]._startDate) || (deduped[0] && deduped[0]._startDate) || "";
const endDate = (companies[0] && companies[0]._endDate) || (deduped[0] && deduped[0]._endDate) || "";
const parseError = (deduped[0] && deduped[0]._parseError) || "";
const sfAccountCount = (deduped[0] && Number(deduped[0]._sfAccountCount)) || 0;
const guardTripped = !parseError && companies.length > 0 && sfAccountCount === 0;
const newOnes = companies.filter((c) => c._isNew);
const existing = companies.filter((c) => !c._isNew);

let subject;
let body;

if (parseError) {
  subject = `⚠️ Weekly funding discovery FAILED — ${startDate}–${endDate}`;
  body = [
    "Hi Sales team,",
    "",
    "The weekly funding discovery run hit an error and could not produce results.",
    "",
    `  • Window: ${startDate} → ${endDate}`,
    `  • Error:  ${parseError}`,
    "",
    "No action needed — this is a heads-up that this week's file may be delayed.",
    "",
    "— Automations (n8n)",
  ].join("\n");
} else if (guardTripped) {
  subject = `⚠️ Weekly funding digest ${startDate}–${endDate} · ${companies.length} companies · Salesforce creation SKIPPED`;
  const lines = [];
  lines.push("Hi Sales team,");
  lines.push("");
  lines.push(`Weekly software/tech funding digest (${startDate} → ${endDate}).`);
  lines.push("");
  lines.push("⚠️ SAFETY GUARD TRIPPED: the Salesforce account list came back EMPTY (0 accounts).");
  lines.push("To avoid mass-creating duplicates, NO accounts were created in Salesforce this run.");
  lines.push("Please check the Salesforce connection / permissions, then re-run if needed.");
  lines.push("");
  lines.push(`  • Total found: ${companies.length}`);
  lines.push("  • Created in Salesforce: 0 (creation skipped by guard)");
  lines.push("");
  lines.push("── All companies ──");
  for (const c of companies) {
    lines.push(`- ${c.Name} | ${c.funding_stage || "?"} ${c.funding_amount || ""} | ${c.Website || "no website"}`);
  }
  lines.push("");
  lines.push("Full list with funding details is attached as CSV.");
  lines.push("");
  lines.push("— Automations (n8n)");
  body = lines.join("\n");
} else if (companies.length) {
  subject = `✅ Weekly funding digest ${startDate}–${endDate} · ${companies.length} companies (${newOnes.length} new)`;
  const lines = [];
  lines.push("Hi Sales team,");
  lines.push("");
  lines.push(`Weekly software/tech funding digest (${startDate} → ${endDate}).`);
  lines.push("");
  lines.push(`  • Total found: ${companies.length}`);
  lines.push(`  • New (created in Salesforce): ${newOnes.length}`);
  lines.push(`  • Already in Salesforce: ${existing.length}`);
  lines.push("");
  lines.push("── All companies ──");
  for (const c of companies) {
    const flag = c._isNew ? "NEW" : "EXISTS";
    lines.push(`- [${flag}] ${c.Name} | ${c.funding_stage || "?"} ${c.funding_amount || ""} | ${c.Website || "no website"}`);
  }
  lines.push("");
  lines.push("Full list with funding + Salesforce match status is attached as CSV.");
  lines.push("");
  lines.push("— Automations (n8n)");
  body = lines.join("\n");
} else {
  subject = `✅ Weekly funding digest ${startDate}–${endDate} · no new matches`;
  body = [
    "Hi Sales team,",
    "",
    `No software/tech funding companies were found for ${startDate} → ${endDate}.`,
    "",
    "— Automations (n8n)",
  ].join("\n");
}

const input = $input.first();
const hasAttachment = Boolean(input.binary && input.binary.data);

return [{
  json: {
    subject,
    body,
    hasAttachment,
    outcome: parseError ? "failure" : (guardTripped ? "guard_skipped" : "success"),
    startDate,
    endDate,
    companyCount: companies.length,
    newCount: guardTripped ? 0 : newOnes.length,
  },
  binary: input.binary || {},
}];

// ── Build Failure Email ───────────────────────────────────────────────────
// Fires only when the workflow HARD-fails, via the Error Trigger. Produces the
// failure subject/body for the shared Send Email node. No attachment.
// Code node mode: "Run Once for All Items".

const info = ($input.first() && $input.first().json) || {};
const wf = (info.workflow && info.workflow.name) || "Weekly Funding Discovery";
const exec = info.execution || {};
const errMsg = (exec.error && (exec.error.message || exec.error)) || "Unknown error";
const lastNode = exec.lastNodeExecuted || "unknown node";
const url = exec.url || "";

const subject = `⚠️ Weekly funding discovery FAILED — ${wf}`;

const parts = [
  "Hi Sales team,",
  "",
  "The weekly funding discovery run did NOT complete. No results were produced this run.",
  "",
  `  • Workflow:  ${wf}`,
  `  • Failed at: ${lastNode}`,
  `  • Error:     ${String(errMsg).slice(0, 300)}`,
];
if (url) parts.push(`  • Execution: ${url}`);
parts.push("");
parts.push("No action needed from Sales — this is a heads-up that this week's file may be delayed.");
parts.push("");
parts.push("— Automations (n8n)");

return [{ json: { subject, body: parts.join("\n"), hasAttachment: false, outcome: "failure" } }];
